// What each category of effect means, in plain words.
const EFFECT_CATEGORY: Record<string, string> = {
	Cognitive: 'Changes to thinking, feeling and sense of self: mood, memory, focus, ego, and how time and meaning feel.',
	Physical: 'What happens in the body: energy, temperature, nausea, heart rate, coordination and pain.',
	Visual: 'Changes to what you see, from brighter colours and drifting surfaces to geometry and full hallucinations.',
	Auditory: 'Changes to sound: distortion, enhancement, or hearing things that aren’t there.',
	Tactile: 'Changes to touch and bodily sensation, like tingling or feelings that move across the skin.',
	Multisensory: 'Effects that cross the senses at once, like synaesthesia or a scene that feels completely real.',
	'Smell & Taste': 'Changes to smell and taste, including smells or tastes that aren’t really there.',
	Other: 'Effects that don’t fit neatly anywhere else.',
};

function EffectsBrowse({ q, onEffect }: { q: Q; onEffect: (e: string) => void }) {
	const searchRef = useRef<HTMLInputElement | null>(null);
	useFindKey(searchRef);
	const { open, effectInfo } = useContext(OpenCtx);
	const [filter, setFilter] = useState('');
	const [more, setMore] = useState<Record<string, boolean>>({});
	const [seiOpen, setSeiOpen] = useState(false);
	useEffect(() => {
		const k = (e: KeyboardEvent) => e.key === 'Escape' && setSeiOpen(false);
		window.addEventListener('keydown', k);
		return () => window.removeEventListener('keydown', k);
	}, []);
	const groups = useMemo(() => {
		const g = new Map<string, { name: string; n: number }[]>();
		for (const r of rows(q)) {
			if (filter && !S(r.name).toLowerCase().includes(filter.toLowerCase())) continue;
			const c = S(r.category).replace(' Effects', '') || 'Other';
			if (!g.has(c)) g.set(c, []);
			g.get(c)!.push({ name: S(r.name), n: N(r.n) });
		}
		return [...g.entries()].sort((a, b) => b[1].reduce((x, y) => x + y.n, 0) - a[1].reduce((x, y) => x + y.n, 0));
	}, [q.data, filter]);
	// The one-sentence description, without repeating the effect's own name at the start.
	const blurbOf = (name: string) => {
		const b = effectInfo.get(name.toLowerCase())?.blurb ?? '';
		const t = b.replace(new RegExp(`^${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+(is|are|can be described as|refers to|describes)\\s+((medically\\s+)?(recognized|known|defined)\\s+as\\s+)?`, 'i'), '');
		return t ? t[0].toUpperCase() + t.slice(1) : '';
	};
	const feltOf = (name: string) => {
		const i = effectInfo.get(name.toLowerCase());
		if (!i || i.neg == null) return null;
		return (i.pos ?? 0) >= 0.6 ? { w: 'mostly good', c: C.mint } : i.neg >= 0.55 ? { w: 'mostly rough', c: C.coral } : { w: 'mixed', c: C.lav };
	};
	return (
		<section className="rd-fade">
			<h1 className="text-4xl font-semibold">Effects</h1>
			<p className="mt-2" style={{ color: C.soft }}>
				Everything people described in their stories, grouped by kind. Each card says what the effect is, how many stories mention it, and how people usually felt about it.
			</p>
			{/* A slim credit strip; the full story of Effect Index opens in a pop-up. */}
			<div className="rd-card mt-5 flex flex-wrap items-center gap-x-5 gap-y-3 px-5 py-4" style={{ background: 'rgba(110,215,140,.14)', borderColor: 'rgba(143,227,164,.45)' }}>
				<span style={{ color: '#fff' }}>
					<SeiLogo width={58} />
				</span>
				<p className="min-w-0 flex-1 text-sm" style={{ color: C.soft, lineHeight: 1.5, minWidth: 240 }}>
					Effect names and descriptions come from the <b style={{ color: '#fff' }}>Effect Index</b>: years of careful community work documenting what each effect feels like, and the coherent taxonomy that groups them here.
				</p>
				<div className="flex flex-wrap gap-2">
					<button className="rd-btn text-sm" onClick={() => setSeiOpen(true)}>
						About Effect Index
					</button>
					<a className="rd-btn text-sm" href="https://www.effectindex.com" target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none', background: '#fff', color: C.deep }}>
						Visit ↗
					</a>
				</div>
			</div>
			{seiOpen && (
				<>
					<div className="rd-scrim" onClick={() => setSeiOpen(false)} style={{ background: 'rgba(20,12,50,.45)' }} />
					<div role="dialog" aria-label="About Effect Index" className="rd-fade fixed left-1/2 top-1/2 overflow-y-auto rounded-3xl p-6 sm:p-8" style={{ zIndex: 41, width: 'min(640px, calc(100vw - 32px))', maxHeight: '86vh', transform: 'translate(-50%, -50%)', background: 'linear-gradient(165deg, #5a4bb0 0%, #4a3d98 100%)', color: '#fff', border: `1px solid ${C.line}`, boxShadow: '0 30px 80px rgba(20,12,50,.5)' }}>
						<div className="flex items-start justify-between gap-4">
							<span style={{ color: '#fff' }}>
								<SeiLogo width={72} />
							</span>
							<button aria-label="Close" onClick={() => setSeiOpen(false)} className="rounded-full p-2" style={{ color: C.soft, background: 'rgba(255,255,255,.1)' }}>
								<X size={16} />
							</button>
						</div>
						<h2 className="mt-4 text-2xl font-semibold">About Effect Index</h2>
						<div className="mt-3 grid gap-3" style={{ color: C.soft, lineHeight: 1.65 }}>
							<p>
								The effects on this page, their names, categories and descriptions, come from the <b style={{ color: '#fff' }}>Effect Index</b> (SEI), hosted at Effect Index. It’s a formal, structured documentation of the many distinct states people can experience under hallucinogens and other substances, each described on its own, apart from any one drug.
							</p>
							<p>
								The aim is a shared vocabulary: words for experiences people used to call indescribable, so they can be talked about, compared and studied. Many effects there come with image, video or audio <i>replications</i> that show what they look or sound like, which you’ll only find on their site.
							</p>
							<p>
								Effect Index was founded in 2017 by Josie Kins, who also founded PsychonautWiki, and is built by a community of contributors. It’s years of careful work, and it’s the reason this page can explain anything at all.
							</p>
							<p>
								How re:dose uses it: our close readings tag which of these effects show up in each story, and when. That’s where the story counts and the “mostly good / rough” come from. Every effect links back to its full page on Effect Index.
							</p>
						</div>
						<div className="mt-5 flex flex-wrap gap-2 text-sm font-semibold">
							{(
								[
									['Visit Effect Index', 'https://www.effectindex.com', true],
									['Support their work', 'https://www.effectindex.com/donate', false],
									['Their Discord', 'https://www.effectindex.com/discord', false],
									['r/replications', 'https://reddit.com/r/replications', false],
								] as const
							).map(([label, href, main]) => (
								<a key={label} href={href} target="_blank" rel="noopener noreferrer" className="rounded-full px-4 py-2" style={{ textDecoration: 'none', background: main ? '#fff' : 'rgba(255,255,255,.06)', color: main ? C.deep : '#fff', border: `1px solid ${main ? '#fff' : C.line}` }}>
									{label} ↗
								</a>
							))}
						</div>
					</div>
				</>
			)}
			<input ref={searchRef} value={filter} onChange={(e) => setFilter(e.target.value)} placeholder="Search effects" className="rd-card mt-6 w-full px-5 py-3 text-base" style={{ borderRadius: 999, color: C.text, outline: 'none' }} />
			{!q.isLoading && groups.length > 1 && (
				<nav className="mt-4 flex flex-wrap gap-2" aria-label="Kinds of effect">
					{groups.map(([cat, list]) => (
						<button key={cat} className="rd-nav" style={{ fontSize: 13, padding: '5px 12px', border: `1px solid ${C.line}` }} onClick={() => document.getElementById(`fx-${cat}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })}>
							{cat} <span style={{ color: C.faint }}>{list.length}</span>
						</button>
					))}
				</nav>
			)}
			{q.isLoading ? (
				<Loading height={240} className="mt-6" />
			) : (
				<div className="mt-10 grid gap-14">
					{groups.map(([cat, list]) => {
						const shown = more[cat] || filter ? list : list.slice(0, 12);
						return (
							<section key={cat} id={`fx-${cat}`} style={{ scrollMarginTop: 16 }}>
								<h2 className="text-2xl font-semibold">
									{cat} <span className="text-base font-normal" style={{ color: C.faint }}>{list.length} effects</span>
								</h2>
								{EFFECT_CATEGORY[cat] && <p className="mt-1 max-w-3xl" style={{ color: C.soft }}>{EFFECT_CATEGORY[cat]}</p>}
								<div className="mt-5 grid gap-3" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(270px, 1fr))' }}>
									{shown.map((e) => {
										const felt = feltOf(e.name);
										const blurb = blurbOf(e.name);
										return (
											<button key={e.name} onClick={() => onEffect(e.name)} className="rd-card rd-hover grid content-start gap-2 p-4 text-left">
												<span className="flex items-center gap-2 font-semibold">
													<span className="rd-dot" style={{ background: TONE_DOT[effectTone(effectInfo.get(e.name.toLowerCase()))] }} />
													{e.name}
												</span>
												{blurb && (
													<span className="text-sm" style={{ color: C.soft, lineHeight: 1.45, display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
														{blurb}
													</span>
												)}
												<span className="flex items-center gap-2 text-xs" style={{ color: C.faint }}>
													{e.n.toLocaleString()} {e.n === 1 ? 'story' : 'stories'}
													{felt && (
														<>
															<span>·</span>
															<span style={{ color: felt.c }}>{felt.w}</span>
														</>
													)}
												</span>
											</button>
										);
									})}
								</div>
								{!filter && list.length > 12 && (
									<button className="mt-3 text-sm font-semibold" style={{ color: C.soft, textDecoration: 'underline', textUnderlineOffset: 4 }} onClick={() => setMore({ ...more, [cat]: !more[cat] })}>
										{more[cat] ? 'Show fewer' : `Show all ${list.length} ${cat.toLowerCase()} effects`}
									</button>
								)}
							</section>
						);
					})}
				</div>
			)}
			<Err q={q} />
		</section>
	);
}

// ── Browse: substances ────────────────────────────────────────────

// Top combinations for one substance, with how they went and any interaction note.
const focusCombosSQL = (sub: string, limit = 8) => `
WITH co AS (
  SELECT d2.canonical_substance AS s, count(DISTINCT d1.report_id) AS n
  FROM ${DB}."report_doses" d1 JOIN ${DB}."report_doses" d2 USING (report_id)
  WHERE d1.canonical_substance = '${esc(sub)}' AND d2.canonical_substance IS NOT NULL AND d2.canonical_substance <> '${esc(sub)}'
  GROUP BY 1 ORDER BY n DESC, 1 LIMIT ${limit}
),
pairrep AS (
  SELECT DISTINCT d2.canonical_substance AS s, d1.report_id
  FROM ${DB}."report_doses" d1 JOIN ${DB}."report_doses" d2 USING (report_id)
  WHERE d1.canonical_substance = '${esc(sub)}' AND d2.canonical_substance IN (SELECT s FROM co)
),
val AS (
  SELECT report_id, avg(valence) AS v FROM ${DB}."timeline_sentiment"
  WHERE report_id IN (SELECT report_id FROM pairrep) GROUP BY 1
),
${pairSevCTEs(`SELECT '${esc(sub)}' AS a, s AS b FROM co`)},
stats AS (
  SELECT p.s, count(e.report_id) AS n_llm,
    avg((e.overall_sentiment = 'positive')::INT) AS pos, avg((e.overall_sentiment = 'negative')::INT) AS neg,
    avg(val.v) AS v
  FROM pairrep p LEFT JOIN ${DB}."llm_extractions" e USING (report_id) LEFT JOIN val USING (report_id)
  GROUP BY 1
)
SELECT co.s, co.n, stats.n_llm, stats.pos, stats.neg, stats.v, ps.sev, ps.status, ps.note
FROM co LEFT JOIN stats USING (s) LEFT JOIN pairsev ps ON ps.b = co.s
ORDER BY co.n DESC, co.s`;

// How reports with only this substance went.
const aloneSQL = (sub: string) => `
WITH rs AS (
  SELECT report_id, list(DISTINCT canonical_substance) AS subs
  FROM ${DB}."report_doses" WHERE canonical_substance IS NOT NULL GROUP BY 1
),
alone AS (SELECT report_id FROM rs WHERE len(subs) = 1 AND subs[1] = '${esc(sub)}')
SELECT count(*) AS n, count(e.report_id) AS n_llm,
  avg((e.overall_sentiment = 'positive')::INT) AS pos, avg((e.overall_sentiment = 'negative')::INT) AS neg
FROM alone LEFT JOIN ${DB}."llm_extractions" e USING (report_id)`;

function OutcomeBar({ pos, neg, n }: { pos: unknown; neg: unknown; n: number }) {
	if (n < 3) return <span className="text-xs" style={{ color: C.faint }}>too few close reads</span>;
	return (
		<span className="flex items-center gap-2" style={{ minWidth: 0 }}>
			<span className="flex overflow-hidden rounded-full" style={{ width: 90, height: 6, background: 'rgba(255,255,255,.08)', flexShrink: 0 }}>
				<span style={{ width: `${Math.round(100 * N(pos))}%`, background: C.mint }} />
				<span style={{ flex: 1 }} />
				<span style={{ width: `${Math.round(100 * N(neg))}%`, background: C.coral }} />
			</span>
			<span className="text-xs tabular-nums" style={{ color: C.soft, whiteSpace: 'nowrap' }}>
				<span style={{ color: C.mint }}>{Math.round(100 * N(pos))}%</span> good · <span style={{ color: C.coral }}>{Math.round(100 * N(neg))}%</span> rough
			</span>
		</span>
	);
}

// What people most often took it with, whether the mix carries a warning, and how it went.
function CombosList({ name, onCombo, bare }: { name: string; onCombo: (a: string, b: string) => void; bare?: boolean }) {
	const { classOf } = useContext(OpenCtx);
	const combosQ = useSQLQuery(focusCombosSQL(name));
	return (
		<>
			{!bare && <span className="rd-label">Most often combined with</span>}
			{combosQ.isLoading ? (
				<div className="mt-3 flex items-center justify-center" style={{ height: 180 }} aria-busy="true" />
			) : rows(combosQ).length === 0 ? (
				<EmptyNote className="mt-2">No combinations on record yet.</EmptyNote>
			) : (
				<div className="mt-2 grid">
					{rows(combosQ).map((r) => {
						const other = S(r.s);
						const sev = r.sev == null ? 0 : N(r.sev);
						return (
							<button
								key={other}
								onClick={() => onCombo(name, other)}
								className="rd-hover grid items-center rounded-xl px-2 py-3 text-left"
								style={{ gridTemplateColumns: 'minmax(0, 1fr) auto 16px', columnGap: 12, rowGap: 6, borderTop: `1px solid ${C.line}` }}
							>
								<span className="flex items-center gap-2 font-semibold" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} title={other}>
									<ClassIcon cls={classOf(other)} size={16} color="var(--rd-accent)" />
									{short(other)}
								</span>
								<span className="text-xs font-semibold" style={{ whiteSpace: 'nowrap' }} title={S(r.note) || undefined}>
									{sev ? <RiskPill sev={sev} small /> : r.status ? <span style={{ color: C.mint }}>low risk</span> : <span style={{ color: C.faint }}>no note</span>}
								</span>
								<ChevronRight size={14} color={C.faint} style={{ gridRow: '1 / 3', gridColumn: 3 }} />
								<span className="flex flex-wrap items-center gap-x-3 gap-y-1" style={{ gridColumn: '1 / 3' }}>
									<span className="text-xs" style={{ color: C.faint, whiteSpace: 'nowrap' }}>{N(r.n)} reports together</span>
									<OutcomeBar pos={r.pos} neg={r.neg} n={N(r.n_llm)} />
								</span>
							</button>
						);
					})}
				</div>
			)}
			<p className="mt-3 text-xs" style={{ color: C.faint }}>
				Good / rough from closely read reports. “No note” isn’t the same as safe.
				<span className="ml-2 inline-block align-middle">
					<TripSitBadge />
				</span>
			</p>
		</>
	);
}

// ── Mixing ────────────────────────────────────────────────────────
// TripSit's chart for every group this substance belongs to: each other group, its rating and note, and which of our
// substances it covers.
const knownMixSQL = (name: string) => `
WITH mine AS (SELECT group_key FROM ${DB}."tripsit_group_members" WHERE substance = '${esc(name)}'),
pairs AS (
  SELECT CASE WHEN c.group_a IN (SELECT group_key FROM mine) THEN c.group_b ELSE c.group_a END AS grp, c.status, c.severity_rank AS rank, c.note
  FROM ${DB}."tripsit_combos" c
  WHERE c.group_a IN (SELECT group_key FROM mine) OR c.group_b IN (SELECT group_key FROM mine)
),
mem AS (SELECT group_key, list(substance ORDER BY substance) AS members FROM ${DB}."tripsit_group_members" GROUP BY 1)
SELECT p.grp, max(p.rank) AS rank, arg_max(p.status, p.rank) AS status, arg_max(p.note, p.rank) AS note, any_value(mem.members) AS members
FROM pairs p LEFT JOIN mem ON mem.group_key = p.grp
WHERE p.grp NOT IN (SELECT group_key FROM mine)
GROUP BY 1 ORDER BY rank DESC, grp`;

const TS_GROUP: Record<string, string> = {
	maois: 'MAOIs', ssris: 'SSRIs', nbomes: 'NBOMes', '2c-x': '2C-x', '2c-t-x': '2C-T-x', '5-meo-xxt': '5-MeO-xxT', dox: 'DOx', 'ghb/gbl': 'GHB / GBL',
	amt: 'αMT', mxe: 'MXE', pcp: 'PCP', lsd: 'LSD', dmt: 'DMT', mdma: 'MDMA', benzodiazepines: 'Benzos', amphetamines: 'Amphetamines', mushrooms: 'Mushrooms',
};
const tsGroup = (k: string) => TS_GROUP[k] ?? k.replace(/\b\w/g, (c) => c.toUpperCase());
const TS_PHRASE: Record<string, string> = {
	'Low Risk & Synergy': 'Low risk, and the effects add up.',
	'Low Risk & No Synergy': 'Low risk, and they barely change each other.',
	'Low Risk & Decrease': 'Low risk, and one dulls the other.',
	Caution: 'Take care with this one.',
	Unsafe: 'There’s a real risk of harm.',
	Dangerous: 'Avoid this combination.',
};
const TS_FALLBACK: Record<number, string> = {
	3: 'TripSit rates this pair as dangerous. Don’t mix them.',
	2: 'TripSit rates this pair as unsafe: a real risk of harm, even at ordinary doses.',
	1: 'TripSit says to take care with this pair, especially at higher doses.',
};
const LANES = [
	{ k: 0, label: 'Low risk', c: C.mint },
	{ k: 1, label: 'Caution', c: RISK[1].c },
	{ k: 2, label: 'Unsafe', c: RISK[2].c },
	{ k: 3, label: 'Dangerous', c: RISK[3].c },
];
type Mix = { key: string; label: string; lane: number; n: number; status: string; note: string; members: string[]; known: boolean; r?: Record<string, unknown> };

// Mixing: what people actually mix it with, grouped by TripSit's rating (most dangerous first), most mixed first in each
// group. Each row: the name, TripSit's note, how it went when there's enough to say, and a link to the stories.
// Pairs TripSit warns about that people rarely mix are in Health Risks.
const MIX_GROUPS = [
	{ sev: 3, label: 'Dangerous', c: RISK[3].c },
	{ sev: 2, label: 'Unsafe', c: RISK[2].c },
	{ sev: 1, label: 'Caution', c: RISK[1].c },
	{ sev: 0, label: 'Low risk', c: C.mint },
	{ sev: -1, label: 'No rating', c: 'rgba(255,255,255,.55)' },
];
function MixingBoard({ name, onCombo }: { name: string; onCombo: (a: string, b: string) => void }) {
	const commonQ = useSQLQuery(focusCombosSQL(name, 12));
	const knownQ = useSQLQuery(knownMixSQL(name));
	const known = rows(knownQ).map((r) => ({ rank: N(r.rank), status: S(r.status), note: S(r.note), members: L(r.members).map(String) }));
	const mixes = rows(commonQ).map((r) => {
		const g = known.find((k) => k.members.includes(S(r.s)));
		const sev = r.sev != null ? N(r.sev) : r.status ? 0 : -1;
		return { key: S(r.s), label: short(S(r.s)), sev, n: N(r.n), status: S(r.status) || g?.status || '', note: S(r.note) || (sev >= 0 ? g?.note ?? '' : ''), r };
	});
	const head = <ArticleH2 icon={Link2} sub="What it’s mixed with and how risky each mix is, including pairs nobody has written about yet. Not medical advice.">Combos</ArticleH2>;
	if (commonQ.isLoading || knownQ.isLoading)
		return (
			<section id="combos" data-rd-safe="" className="mt-24" style={{ scrollMarginTop: 16 }}>
				{head}
				<Loading height={300} className="mt-5" quiet />
			</section>
		);
	if (!mixes.length)
		return (
			<section id="combos" data-rd-safe="" className="mt-24" style={{ scrollMarginTop: 16 }}>
				{head}
				<p className="mt-4 text-sm" style={{ color: C.soft }}>Nobody in our reports mixed {short(name)} with anything else yet. What TripSit knows about mixing it is below.</p>
			</section>
		);
	const risky = mixes.filter((m) => m.sev >= 2);
	const top = [...mixes].sort((a, b) => b.n - a.n).slice(0, 3).map((m) => m.label);
	return (
		<section id="combos" data-rd-safe="" className="mt-24" style={{ scrollMarginTop: 16 }}>
		{head}
		<div className="mt-5">
			<p style={{ color: C.soft, lineHeight: 1.6 }}>
				People most often mix it with <b style={{ color: '#fff' }}>{top.slice(0, -1).join(', ')}{top.length > 1 ? ' and ' : ''}{top[top.length - 1]}</b>.{' '}
				{risky.length ? `TripSit rates ${risky.map((m) => m.label).join(' and ')} as ${risky.some((m) => m.sev === 3) ? 'dangerous or unsafe' : 'unsafe'} with it.` : 'None of these common mixes is rated unsafe by TripSit.'}
			</p>
			<div className="mt-8 grid gap-8">
				{MIX_GROUPS.map((g) => {
					const list = mixes.filter((m) => m.sev === g.sev).sort((a, b) => b.n - a.n);
					if (!list.length) return null;
					return (
						<div key={g.sev}>
							<div className="mb-2 flex items-center gap-2 text-sm font-semibold" style={{ color: g.c }}>
								{g.sev >= 1 ? <AlertTriangle size={14} strokeWidth={2.5} /> : <span className="rd-dot" style={{ width: 8, height: 8, background: g.c }} />}
								{g.label}
								<span className="tabular-nums" style={{ color: C.faint, fontWeight: 500 }}>{list.length}</span>
							</div>
							{list.map((m) => (
								<div key={m.key} className="grid items-start gap-x-6 py-3" style={{ gridTemplateColumns: 'minmax(0, 1fr) auto', borderTop: `1px solid ${C.line}` }}>
									<div className="min-w-0">
										<div className="font-semibold" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} title={m.key}>{m.label}</div>
										<p className="mt-0.5 text-sm" style={{ color: C.soft, lineHeight: 1.55, maxWidth: 680 }}>
											{m.sev >= 0 ? m.note || TS_FALLBACK[m.sev] || TS_PHRASE[m.status] || '' : 'TripSit’s chart doesn’t rate this pair. That doesn’t make it safe.'}
										</p>
										{N(m.r.n_llm) >= 3 && (
											<p className="mt-1 text-xs tabular-nums" style={{ color: C.faint }}>
												In the stories: <span style={{ color: C.mint }}>{Math.round(100 * N(m.r.pos))}% went well</span>, <span style={{ color: C.coral }}>{Math.round(100 * N(m.r.neg))}% rough</span>
											</p>
										)}
									</div>
									<button onClick={() => onCombo(name, m.key)} className="text-sm tabular-nums" style={{ color: '#fff', whiteSpace: 'nowrap', textDecoration: 'underline', textDecorationColor: 'rgba(255,255,255,.3)', textUnderlineOffset: 4 }} title={`Read the stories with both ${m.label} and ${short(name)}`}>
										{m.n.toLocaleString()} {m.n === 1 ? 'story' : 'stories'} →
									</button>
								</div>
							))}
						</div>
					);
				})}
			</div>
			<p className="mt-6 flex flex-wrap items-center gap-2 text-xs" style={{ color: C.faint }}>
				Ratings from TripSit; numbers from our stories. Pairs TripSit warns about that people rarely mix are listed below.
				<TripSitBadge />
			</p>
		</div>
		</section>
	);
}

// Known risks: everything TripSit's chart warns about for this substance, worst first, in plain words, all shown.
function KnownRisks({ name }: { name: string }) {
	const q = useSQLQuery(knownMixSQL(name));
	const list = rows(q).map((r) => ({ grp: S(r.grp), rank: N(r.rank), status: S(r.status), note: S(r.note), members: L(r.members).map(String) }));
	const bad = list.filter((k) => k.rank >= 2), care = list.filter((k) => k.rank === 1);
	if (q.isLoading) return null;
	const row = (k: (typeof list)[number]) => (
		<div key={k.grp} className="grid gap-x-5 gap-y-1.5 py-4 rd-g-risk" style={{ borderTop: `1px solid ${C.line}` }}>
			<div className="rd-risk-head">
				<div className="font-semibold" style={{ whiteSpace: 'nowrap' }}>{tsGroup(k.grp)}</div>
				<RiskPill sev={k.rank} small />
			</div>
			<div className="min-w-0">
				<p style={{ color: C.soft, lineHeight: 1.6 }}>{k.note || TS_FALLBACK[k.rank]}</p>
				{k.members.length > 1 && (
					<p className="mt-1 text-xs" style={{ color: C.faint }}>
						Includes {k.members.slice(0, 5).map(short).join(', ')}
						{k.members.length > 5 ? ` and ${k.members.length - 5} more` : ''}
					</p>
				)}
			</div>
		</div>
	);
	return (
		<section id="risks-more" data-rd-safe="" className="mt-14" style={{ scrollMarginTop: 16 }}>
			<h3 className="text-xl font-semibold">Other pairs to watch</h3>
			<p className="mt-1 text-sm" style={{ color: C.faint }}>Mostly from TripSit’s combination chart.</p>
			<ul className="mt-6 grid gap-3 text-sm" style={{ color: C.soft, lineHeight: 1.6 }}>
				{[
					'Mixing is where most of the danger is. Two things that are fine alone can be risky together.',
					'If a mix isn’t listed, that doesn’t mean it’s safe. It may just not be studied.',
					'Effects can stack for longer than you expect, so leave plenty of time between doses and between substances.',
				].map((t) => (
					<li key={t} className="flex gap-3">
						<span className="rd-dot mt-2" style={{ width: 6, height: 6, background: C.lav, flexShrink: 0 }} />
						{t}
					</li>
				))}
			</ul>
			{list.length > 0 ? (
				<div className="mt-8">
					{bad.length > 0 ? bad.map(row) : <p className="py-4 text-sm" style={{ color: C.faint, borderTop: `1px solid ${C.line}` }}>TripSit doesn’t mark any combination with {short(name)} as unsafe or dangerous.</p>}
					{care.map(row)}
				</div>
			) : (
				<p className="mt-6 text-sm" style={{ color: C.faint }}>{short(name)} isn’t on TripSit’s combination chart, so check each mix carefully before trying it.</p>
			)}
			<p className="mt-5 flex flex-wrap items-center gap-2 text-xs" style={{ color: C.faint }}>
				Notes are TripSit’s own words.
				<TripSitBadge />
			</p>
			<OtherHarms name={name} />
		</section>
	);
}

function FocusPanel({ name, onPick, onCombo, onClose }: { name: string; onPick: (s: string) => void; onCombo: (a: string, b: string) => void; onClose: () => void }) {
	const { open, classOf } = useContext(OpenCtx);
	const aloneQ = useSQLQuery(aloneSQL(name));
	const timingQ = useSQLQuery(timingSQL([name]));
	const t = rows(timingQ).find((r) => S(r.route) === '*');
	const al = rows(aloneQ)[0];
	return (
		<div className="rd-card rd-in mt-6 p-5 sm:p-6" onClick={(e) => e.stopPropagation()}>
			<div className="flex flex-wrap items-center justify-between gap-3">
				<h2 className="flex items-center gap-3 text-2xl font-semibold" style={{ whiteSpace: 'nowrap' }}>
					<ClassIcon cls={classOf(name)} size={22} color="var(--rd-accent)" />
					{short(name)}
				</h2>
				<div className="flex items-center gap-2">
					<button className="rd-btn" style={{ background: '#fff', color: C.deep, padding: '5px 12px', fontSize: 13 }} onClick={() => onPick(name)}>
						Open page
					</button>
					<button className="rd-btn" aria-label="Close" style={{ padding: 7 }} onClick={onClose}>
						<X size={14} />
					</button>
				</div>
			</div>

			<div className="mt-4 grid gap-1 text-sm" style={{ color: C.soft }}>
				<span className="rd-label">On its own</span>
				{timingQ.isLoading || aloneQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 20 }} />
				) : (
					<div className="flex flex-wrap items-center gap-x-5 gap-y-2">
						<span style={{ fontFamily: SERIF, fontSize: 17, color: C.text }}>
							{t ? `Kicks in ~${fmtDur(N(t.on_m))}, strongest ~${fmtDur(N(t.pk_m))}, fades by ~${fmtDur(N(t.end_m))}.` : 'Not enough close reads to time it.'}
						</span>
						{al && <OutcomeBar pos={al.pos} neg={al.neg} n={N(al.n_llm)} />}
					</div>
				)}
			</div>

			<div className="mt-6">
				<CombosList name={name} onCombo={onCombo} />
			</div>
		</div>
	);
}

// Kinds of substance for the Substances index, with what each kind generally does, in plain words.
const SUBSTANCE_KIND: Record<string, { label: string; about: string }> = {
	psychedelic: { label: 'Psychedelics', about: 'Change perception, thinking and sense of self: visuals, meaning, and time running strangely.' },
	stimulant: { label: 'Stimulants', about: 'Raise energy, alertness and heart rate, and often cut appetite and sleep.' },
	depressant: { label: 'Depressants', about: 'Slow the nervous system down: relaxation, sedation, lowered inhibitions. Mixing depressants is especially risky.' },
	hypnotic: { label: 'Depressants', about: 'Slow the nervous system down: relaxation, sedation, lowered inhibitions. Mixing depressants is especially risky.' },
	dissociative: { label: 'Dissociatives', about: 'Create distance from the body and surroundings, from numbness to full detachment.' },
	opioid: { label: 'Opioids', about: 'Relieve pain and bring warmth and calm, but slow breathing, especially with other depressants.' },
	entactogen: { label: 'Entactogens', about: 'Bring feelings of closeness, empathy and openness, often with stimulation.' },
	cannabinoid: { label: 'Cannabinoids', about: 'Cannabis and related compounds: relaxation, euphoria and shifts in perception.' },
	deliriant: { label: 'Deliriants', about: 'Cause confusion and very real-seeming hallucinations that are hard to tell from reality; rarely enjoyable.' },
	hallucinogen: { label: 'Other hallucinogens', about: 'Hallucinogens that don’t follow the classic psychedelic pattern.' },
	nootropic: { label: 'Nootropics', about: 'Taken for focus, memory or staying awake.' },
	eugeroic: { label: 'Nootropics', about: 'Taken for focus, memory or staying awake.' },
	other: { label: 'Other', about: 'Substances that don’t fall under one main kind, groups of drugs, or ones not classified yet.' },
};

// A little more on each kind, for its own page: how they work, what they're like, and what to watch for.
