function Spunion({ tips, lift, autoOpen, onPoke }: { tips: string[]; lift: boolean; autoOpen: boolean; onPoke?: () => void }) {
	const [i, setI] = useState(0);
	const [open, setOpen] = useState(autoOpen);
	const meRef = useRef<HTMLButtonElement | null>(null);
	const [hop, setHop] = useState(false);
	const key = tips.join('|');
	useEffect(() => {
		setI(0);
		setOpen(autoOpen);
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [key]);
	if (!tips.length) return null;
	const tip = tips[i % tips.length];
	// Every so often he does a little double bounce, just to say hi.
	useEffect(() => {
		const timer = setInterval(() => {
			setHop(true);
			setTimeout(() => setHop(false), 950);
		}, 8000);
		return () => clearInterval(timer);
	}, []);
	const next = () => {
		onPoke?.();
		setHop(true);
		setTimeout(() => setHop(false), 950);
		if (open) setI(i + 1);
		setOpen(true);
	};
	return (
		<div className={`sp-wrap ${lift ? 'lift' : ''}`}>
			<style>{SPUNION_CSS}</style>
			{open && (
				<div key={tip} className="sp-bubble rd-in" role="status">
					{tip}
					{/Discord/.test(tip) && (
						<div className="mt-3">
							<a href={REDOSE_DISCORD} target="_blank" rel="noopener noreferrer" className="rd-discord">
								<DiscordIcon size={14} />
								Join us on Discord
							</a>
						</div>
					)}
					<button onClick={() => setOpen(false)} aria-label="Hide tip" style={{ position: 'absolute', top: 9, right: 9, color: 'rgba(255,255,255,.6)' }}>
						<X size={14} />
					</button>
				</div>
			)}
			<button ref={meRef} className={`sp-me ${hop ? 'hop' : ''}`} onClick={next} aria-label={open ? 'Spunion: next tip' : 'Spunion: show a tip'} title="Spunion">
				<SpunionSvg />
			</button>
		</div>
	);
}

// General harm-reduction tips Spunion cycles through after the page's own.
const SPUNION_TIPS = [
	'Start low and go slow, especially with something new.',
	'Most of the risk is in mixing. Check a combination before you try it.',
	'Testing kits can tell you what’s really in your stuff.',
	'Effects can take a while. Waiting before taking more is never wrong.',
	'Rough time? You’re not alone. The re:dose community is on Discord.',
];

// A faint field of molecules behind everything: real ring shapes (benzene, naphthalene, indole, phenethylamine,
// tryptamine) scattered over a big tile, each turned and sized its own way so the pattern doesn't read as a repeat.
const MOLECULE_SVG = (() => {
	let seed = 20261023;
	const rnd = () => {
		seed = (seed + 0x6d2b79f5) | 0;
		let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
		t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	};
	const r = 22, a = r * Math.cos(Math.PI / 6);
	const f = (n: number) => n.toFixed(1);
	type P = [number, number];
	const hex = (cx: number, cy: number): P[] => [30, 90, 150, 210, 270, 330].map((d) => [cx + r * Math.cos((d * Math.PI) / 180), cy + r * Math.sin((d * Math.PI) / 180)]);
	const pent = (x0: number): P[] => {
		const R = r * 0.8507, cx = x0 + r * 0.688;
		return [144, 216, 288, 0, 72].map((d) => [cx + R * Math.cos((d * Math.PI) / 180), R * Math.sin((d * Math.PI) / 180)]);
	};
	const ring = (pts: P[]) => `M${pts.map(([x, y]) => `${f(x)} ${f(y)}`).join(' L')} Z`;
	// Inner lines on every other edge: the double bonds of an aromatic ring.
	const doubles = (pts: P[], c: P) =>
		pts
			.filter((_, i) => i % 2 === 0)
			.map((p, k) => {
				const q = pts[(k * 2 + 1) % pts.length];
				const s = (v: P): P => [c[0] + (v[0] - c[0]) * 0.74, c[1] + (v[1] - c[1]) * 0.74];
				const [x1, y1] = s(p), [x2, y2] = s(q);
				return `M${f(x1)} ${f(y1)} L${f(x2)} ${f(y2)}`;
			})
			.join(' ');
	const chain = (from: P, steps: number, up = -1): P[] => {
		const out: P[] = [from];
		for (let i = 0; i < steps; i++) {
			const [x, y] = out[out.length - 1];
			out.push([x + a, y + (i % 2 === 0 ? up : -up) * (r / 2)]);
		}
		return out;
	};
	const line = (pts: P[]) => `M${pts.map(([x, y]) => `${f(x)} ${f(y)}`).join(' L')}`;
	const dots = (pts: P[], big: P[] = []) =>
		pts.map(([x, y]) => `<circle cx='${f(x)}' cy='${f(y)}' r='2.6'/>`).join('') + big.map(([x, y]) => `<circle cx='${f(x)}' cy='${f(y)}' r='4.6'/>`).join('');
	const shapes: (() => [string, string])[] = [
		() => { const h = hex(0, 0); return [ring(h) + ' ' + doubles(h, [0, 0]), dots(h)]; },
		() => { const h1 = hex(0, 0), h2 = hex(2 * a, 0); return [ring(h1) + ' ' + ring(h2) + ' ' + doubles(h1, [0, 0]), dots([...h1, ...h2])]; },
		() => { const h = hex(0, 0), p5 = pent(a); return [ring(h) + ' ' + ring(p5) + ' ' + doubles(h, [0, 0]), dots([...h, ...p5.slice(2)], [p5[3]])]; },
		() => { const h = hex(0, 0), c = chain(h[5], 3); return [ring(h) + ' ' + doubles(h, [0, 0]) + ' ' + line(c), dots([...h, ...c.slice(1, -1)], [c[c.length - 1]])]; },
		() => { const h = hex(0, 0), p5 = pent(a), c = chain(p5[4], 3, 1); return [ring(h) + ' ' + ring(p5) + ' ' + doubles(h, [0, 0]) + ' ' + line(c), dots([...h, ...p5.slice(2), ...c.slice(1, -1)], [p5[3], c[c.length - 1]])]; },
		() => { const c = chain([-2 * a, 0], 4); const br: P = [c[2][0], c[2][1] - r]; return [line(c) + ' ' + line([c[2], br]), dots(c.slice(0, -1), [c[c.length - 1], br])]; },
	];
	// Scatter them loosely (no two too close, measured across the tile's wrap-around), and draw any that cross an
	// edge again on the far side, so the tile joins up without a seam.
	const W = 1100, gap = 175, placed: P[] = [];
	for (let tries = 0; tries < 2000 && placed.length < 26; tries++) {
		const c: P = [rnd() * W, rnd() * W];
		const near = placed.some(([x, y]) => {
			const dx = Math.min(Math.abs(x - c[0]), W - Math.abs(x - c[0])), dy = Math.min(Math.abs(y - c[1]), W - Math.abs(y - c[1]));
			return dx * dx + dy * dy < gap * gap;
		});
		if (!near) placed.push(c);
	}
	let body = '';
	for (const [x, y] of placed) {
		const [path, atoms] = shapes[Math.floor(rnd() * shapes.length)]();
		const sc = 0.8 + rnd() * 0.6, rot = Math.floor(rnd() * 360);
		const g = `rotate(${rot}) scale(${sc.toFixed(2)})' stroke-width='${(1.3 / sc).toFixed(2)}'><path d='${path}'/><g fill='white' stroke='none'>${atoms}</g></g>`;
		const xs = [x, ...(x < 110 ? [x + W] : x > W - 110 ? [x - W] : [])], ys = [y, ...(y < 110 ? [y + W] : y > W - 110 ? [y - W] : [])];
		for (const px of xs) for (const py of ys) body += `<g transform='translate(${f(px)} ${f(py)}) ${g}`;
	}
	return `<svg xmlns='http://www.w3.org/2000/svg' width='${W}' height='${W}' viewBox='0 0 ${W} ${W}' fill='none' stroke='white' stroke-linecap='round' stroke-linejoin='round'>${body}</svg>`;
})();
const MOLECULES = `url("data:image/svg+xml,${encodeURIComponent(MOLECULE_SVG)}")`;

// ── Main ──────────────────────────────────────────────────────────

type Q = ReturnType<typeof useSQLQuery>;

// The preview's connecting screen. Every time Spunion lands (the bounce animation's own loop event, so it stays in
// step), a new background colour washes out from his feet and a ring of colour rolls out through the molecules.
const START_WASHES = ['#5b2c74', '#22497f', '#4a3d9c'];
const START_RINGS = ['#fc6c84', '#5cdfe4', '#b3a8f0'];
export function StartScreen() {
	const [lands, setLands] = useState<number[]>([]);
	const land = (e: React.AnimationEvent) => {
		if (e.animationName === 'rd-bounce') setLands((l) => [...l.slice(-3), (l[l.length - 1] ?? -1) + 1]);
	};
	return (
		<main className="rd rd-fx-rainbow rd-start" style={{ minHeight: '100vh', background: BG, position: 'relative', isolation: 'isolate', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
			<style>{CSS}</style>
			{lands.map((n) => (
				<div key={`w${n}`} aria-hidden className="rd-wash" style={{ background: START_WASHES[n % 3] }} />
			))}
			<div aria-hidden className="rd-molecules" style={{ backgroundImage: MOLECULES }} />
			<div aria-hidden className="rd-molecules b" style={{ backgroundImage: MOLECULES, backgroundPosition: '310px 470px' }} />
			<div aria-hidden className="rd-ripples" style={{ WebkitMaskImage: MOLECULES, maskImage: MOLECULES }}>
				{lands.map((n) => (
					<div key={`r${n}`} className="rd-ripple" style={{ color: START_RINGS[n % 3] }} />
				))}
			</div>
			<span onAnimationIteration={land} style={{ display: 'contents' }}>
				<BouncingSpunion size={88} />
			</span>
		</main>
	);
}

export default function ReportTimelapse() {
	const [savedView, setView] = useDiveState<'home' | 'reports' | 'substances' | 'effects' | 'resources' | 'privacy'>('view', 'home');
	// Easter egg: copy the word "psychedelic" from anywhere on the page, or poke the corner Spunion five times
	// quickly. Esc comes down; it wears off by itself after 30 seconds.
	const [trip, setTrip] = useState(false);
	const pageRef = useRef<HTMLDivElement | null>(null);
	// Homepage: molecules light up around the pointer (a CSS mask that follows it; no re-renders).
	const glowRef = useRef<HTMLDivElement | null>(null);
	useEffect(() => {
		let raf = 0;
		const move = (e: PointerEvent) => {
			cancelAnimationFrame(raf);
			raf = requestAnimationFrame(() => {
				glowRef.current?.style.setProperty('--mx', `${e.clientX}px`);
				glowRef.current?.style.setProperty('--my', `${e.clientY}px`);
			});
		};
		window.addEventListener('pointermove', move);
		return () => (window.removeEventListener('pointermove', move), cancelAnimationFrame(raf));
	}, []);
	const pokes = useRef<number[]>([]);
	const poke = () => {
		const now = Date.now();
		pokes.current = [...pokes.current.filter((t) => now - t < 2500), now];
		if (pokes.current.length >= 5) {
			pokes.current = [];
			setTrip(true);
		}
	};
	useEffect(() => {
		const key = (e: KeyboardEvent) => e.key === 'Escape' && setTrip(false);
		const copy = () => {
			if (/psychedelic/i.test(window.getSelection?.()?.toString() ?? '')) setTrip(true);
		};
		window.addEventListener('keydown', key);
		document.addEventListener('copy', copy);
		return () => {
			window.removeEventListener('keydown', key);
			document.removeEventListener('copy', copy);
		};
	}, []);
	useEffect(() => {
		if (!trip) return;
		const timer = setTimeout(() => setTrip(false), 30000);
		return () => clearTimeout(timer);
	}, [trip]);
	// Old links may still say "about", a page that's gone; they land on the home page.
	const view = (savedView as string) === 'about' ? 'substances' : savedView;
	const [sub, setSub] = useDiveState<string | null>('substance', null);
	const [reportId, setReportId] = useDiveState<string | null>('report', null);
	const [withSub, setWithSub] = useDiveState<string | null>('with', null);
	const [only, setOnly] = useDiveState<boolean>('only', false);
	const [openItem, setOpenItemState] = useDiveState<Open>('open', null);
	const [effect, setEffect] = useDiveState<string | null>('effect', null);
	const [, setKind] = useDiveState<string | null>('kind', null);
	// On an effect's own page, a gentle taste of that effect (see EFFECT_FX); trip mode turns them all on.
	const [fxOff, setFxOff] = useState(false);
	useEffect(() => setFxOff(false), [effect]);
	const pageFx = view === 'effects' && effect ? EFFECT_FX[effect.toLowerCase()] ?? [] : [];
	// Synaesthesia lingers: once you've visited it, its colours stay on as you browse until you turn them off.
	const [synOn, setSynOn] = useState(false);
	useEffect(() => {
		if (effect?.toLowerCase() === 'synaesthesia') setSynOn(true);
	}, [effect]);
	const fx = trip ? ['letters', 'rainbow', 'sway'] : [...(fxOff ? [] : pageFx), ...(synOn ? ['rainbow', 'tint'] : []), ...(view === 'home' ? ['rainbow'] : [])];
	const setOpenItem = (o: Open) => setOpenItemState((o ?? undefined) as Open);
	const [, setAtLink] = useDiveState<number | null>('at', null);

	const pickQ = useSQLQuery(pickListSQL);
	const effectInfoQ = useSQLQuery(effectInfoSQL);
	const effectToneQ = useSQLQuery(effectToneSQL);
	const classesQ = useSQLQuery(classesSQL);
	const classMap = useMemo(() => new Map(rows(classesQ).map((r) => [S(r.name), r.cls == null ? undefined : S(r.cls)])), [classesQ.data]);
	const effectInfo = useMemo(() => {
		const m = new Map<string, EffectInfo>(rows(effectInfoQ).map((r) => [S(r.k), { blurb: S(r.blurb), url: S(r.url) }]));
		for (const r of rows(effectToneQ)) m.set(S(r.k), { ...(m.get(S(r.k)) ?? { blurb: '', url: '' }), neg: N(r.neg), pos: N(r.pos) });
		return m;
	}, [effectInfoQ.data, effectToneQ.data]);

	const onSub = view === 'reports' && !!sub && !reportId;
	const onReport = view === 'reports' && !!reportId;
	const listQ = useSQLQuery(reportListSQL(sub ?? '', withSub, only), { enabled: onSub });
	const comboPairQ = useSQLQuery(reportPairsSQL([sub ?? '', withSub ?? '']), { enabled: onSub && !!withSub });
	const kpiQ = useSQLQuery(kpiSQL(sub ?? '', false), { enabled: onSub });
	const kp = rows(kpiQ)[0];
	// Show each substance on its own clock: a bit past when most people's last effects are noted.
	const horizon = (() => {
		const h = kp && N(kp.n_llm) >= 3 ? Math.max(N(kp.last_h) * 1.6, N(kp.peak_h) * 2.5, 0.4) : 12;
		const nice = [0.25, 0.5, 0.75, 1, 1.5, 2, 3, 4, 6, 8, 10, 12, 16, 24];
		const v = nice.find((x) => x >= h) ?? 24;
		return withSub ? Math.max(v, 6) : v;
	})();
	const curveReady = onSub && !kpiQ.isLoading;
	const curveAllQ = useSQLQuery(curveSQL(sub ?? '', horizon, withSub, only), { enabled: curveReady });
	const denAllQ = useSQLQuery(curveDenSQL(sub ?? '', horizon, withSub, only), { enabled: curveReady });
	// The route picked under Dosage & Duration also drives Effects, when that route has enough close readings.
	const [routePick, setRoutePick] = useDiveState<string | null>('route', null);
	const routeOn = curveReady && !withSub && !!routePick;
	const curveRouteQ = useSQLQuery(curveSQL(sub ?? '', horizon, null, only, routePick), { enabled: routeOn });
	const denRouteQ = useSQLQuery(curveDenSQL(sub ?? '', horizon, null, only, routePick), { enabled: routeOn });
	const routeEnough = routeOn && !denRouteQ.isLoading && N(rows(denRouteQ)[0]?.total) >= 10;
	const curveQ = routeEnough ? curveRouteQ : curveAllQ;
	const denQ = routeEnough ? denRouteQ : denAllQ;
	const effectsRoute = routeOn ? { route: routePick!, used: routeEnough, loading: routeOn && denRouteQ.isLoading } : null;
	const pairTimingQ = useSQLQuery(timingSQL(withSub ? [sub ?? '', withSub] : []), { enabled: onSub && !!withSub });
	const pairMoodQ = useSQLQuery(pairMoodSQL(sub ?? '', withSub ?? '', 24), { enabled: onSub && !!withSub });
	const pairSummaryQ = useSQLQuery(pairSummarySQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const pairEffectsQ = useSQLQuery(pairEffectsSQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const pairSeqQ = useSQLQuery(pairSeqSQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const reportQ = useSQLQuery(reportSQL(reportId ?? ''), { enabled: onReport });
	const marksQ = useSQLQuery(reportMarksSQL(reportId ?? ''), { enabled: onReport });
	const dosesQ = useSQLQuery(reportDosesSQL(reportId ?? ''), { enabled: onReport });
	const obsQ = useSQLQuery(reportObsSQL(reportId ?? ''), { enabled: onReport });
	const doseSubs = useMemo(() => [...new Set(rows(dosesQ).map((d) => S(d.sub)).filter(Boolean))].sort(), [dosesQ.data]);
	const timingQ = useSQLQuery(timingSQL(doseSubs), { enabled: onReport && doseSubs.length > 0 });
	const pairsQ = useSQLQuery(reportPairsSQL(doseSubs), { enabled: onReport && doseSubs.length > 1 });
	const effectsQ = useSQLQuery(effectsBrowseSQL, { enabled: view === 'effects' });

	const effectDetailQ = useSQLQuery(effectDetailSQL(openItem?.name ?? ''), { enabled: openItem?.kind === 'effect' });
	const subDetailQ = useSQLQuery(substanceDetailSQL(openItem?.name ?? ''), { enabled: openItem?.kind === 'substance' });
	const subTimingQ = useSQLQuery(timingSQL(openItem?.kind === 'substance' ? [openItem.name] : []), { enabled: openItem?.kind === 'substance' });

	// Leaving a story also drops its moment, so links to other pages don't carry a stray time.
	const clearReport = () => {
		setReportId(undefined as unknown as null);
		setAtLink(undefined as unknown as null);
	};
	const goSubstance = (s: string) => {
		window.scrollTo?.({ top: 0 });
		setView('reports');
		setSub(s);
		setRoutePick(undefined as unknown as null);
		setWithSub(undefined as unknown as null);
		clearReport();
		setOpenItem(null);
	};
	// Spunion only speaks up when it matters: a risky pair or a first hello. On reports he delivers the mix banner.
	// Remembered for this visit only: nothing is stored in the browser (see the privacy page).
	const [greeted] = useState(() => spunionGreeted);
	useEffect(() => {
		spunionGreeted = true;
	}, []);
	const pairSev = onSub && withSub ? N(rows(comboPairQ)[0]?.sev) : 0;
	// On a substance page his tip comes from its own timing (the same numbers as the page's dose curve), and only when
	// there's something worth saying: slow to kick in, or quick to wear off.
	const subTimingPageQ = useSQLQuery(timingSQL(onSub && !withSub ? [sub!] : []), { enabled: onSub && !withSub });
	const subTip = (() => {
		if (!onSub || withSub) return '';
		const name = short(sub!);
		if (isGroup(sub!)) return `${name} is a group of drugs, not one. Effects and timing depend on which one it really is.`;
		const t = rows(subTimingPageQ).find((r) => S(r.route) === '*');
		if (!t) return '';
		if (N(t.on_m) >= 0.5) return `${name} can take about ${fmtDur(N(t.on_m))} to kick in. Waiting before taking more is never wrong.`;
		if (N(t.end_m) > 0 && N(t.end_m) <= 3) return `${name} usually wears off within about ${fmtDur(N(t.end_m))}, which makes topping up tempting. Pace yourself.`;
		return '';
	})();
	const spunionTips = [
		onReport ? 'Scroll through the story and the timeline follows along. Or press play and I’ll walk you through it.'
		: pairSev >= 2 ? `${short(sub!)} with ${short(withSub!)} is a risky mix. If you go ahead anyway: go low, go slow, and don’t do it alone.`
		: onSub && withSub ? `Here’s how ${short(sub!)} and ${short(withSub!)} tend to go together, from people who tried it.`
		: onSub ? subTip
		: view === 'effects' ? 'Tap an effect to see what it is, and what people had taken when they felt it.'
		: view === 'home' ? 'Hi, I’m Spunion! Search anything you like. Want to talk to real people? The re:dose community is on Discord.'
		: 'Hi, I’m Spunion! Tap a substance to see how it usually goes.',
		...SPUNION_TIPS,
	].filter(Boolean) as string[];
	// He opens his bubble by himself only when it matters; otherwise he waits to be tapped.
	const spunionSpeaks = pairSev >= 2;
	const goReport = (id: string, s: string) => {
		window.scrollTo?.({ top: 0 });
		setView('reports');
		if (s) setSub(s);
		setWithSub(undefined as unknown as null);
		setAtLink(undefined as unknown as null);
		setOpenItem(null);
		setReportId(id);
	};
	const goEffect = (e: string) => {
		setView('effects');
		setEffect(e);
		setOpenItem(null);
		window.scrollTo?.({ top: 0 });
	};
	const goView = (v: 'home' | 'reports' | 'substances' | 'effects' | 'resources' | 'privacy') => {
		window.scrollTo?.({ top: 0 });
		setView(v);
		setRoutePick(undefined as unknown as null);
		setEffect(undefined as unknown as null);
		setSub(undefined as unknown as null);
		setWithSub(undefined as unknown as null);
		setKind(undefined as unknown as null);
		clearReport();
		setOpenItem(null);
	};
	useEffect(() => {
		let link = document.querySelector<HTMLLinkElement>('link[rel~="icon"]');
		if (!link) {
			link = document.createElement('link');
			link.rel = 'icon';
			document.head.appendChild(link);
		}
		link.href = FAVICON;
	}, []);
	// Tab title: the page you're on, then the site ("MDMA – re:dose").
	useEffect(() => {
		const page =
			view === 'home' ? 'Harm reduction, from real experiences'
			: view === 'privacy' ? 'Privacy'
			: view === 'resources' ? 'Resources'
			: view === 'effects' ? effect || 'Effects'
			: view === 'reports' && reportId ? `Story #${reportId.replace('erowid-', '')}`
			: view === 'reports' && sub ? (withSub ? `${short(sub)} + ${short(withSub)}` : short(sub))
			: view === 'reports' ? 'Experiences'
			: 'Substances';
		document.title = `${page} – re:dose`;
	}, [view, sub, withSub, reportId, effect]);
	// Which nav item is "here": a substance or pair page counts as Substances, a story as Stories.
	const navHere = view === 'reports' ? (reportId || !sub ? 'reports' : 'substances') : view;
	const goCombo = (a: string, b: string) => {
		window.scrollTo?.({ top: 0 });
		setView('reports');
		setSub(a);
		setWithSub(b);
		clearReport();
		setOpenItem(null);
	};

	return (
		<GoCtx.Provider value={goSubstance}>
		<OpenCtx.Provider value={{ open: setOpenItem, effectInfo, classOf: (n: string) => classMap.get(n) }}>
			<main className={`rd ${onSub && !withSub && sub === 'Cannabis' ? 'rd-green' : ''}`} style={{ minHeight: '100vh', background: BG, color: C.text, position: 'relative' }}>
				<style>{CSS}</style>
				{fx.includes('letters') && <TripLetters scope={pageRef} gentle={!trip} />}
				{synOn && !(view === 'effects' && effect?.toLowerCase() === 'synaesthesia') && (
					<button className="rd-btn text-xs" onClick={() => setSynOn(false)} style={{ position: 'fixed', left: 16, bottom: 16, zIndex: 50, padding: '6px 12px' }}>
						Synaesthesia is on · Turn off
					</button>
				)}
				{trip && (
					<>
						<button className="rd-btn text-sm" onClick={() => setTrip(false)} style={{ position: 'fixed', top: 14, left: '50%', transform: 'translateX(-50%)', zIndex: 70, background: '#fff', color: C.deep }}>
							Come down (Esc)
						</button>
					</>
				)}
				<div ref={pageRef} className={`px-4 py-6 sm:px-8 sm:py-8 ${fx.includes('sway') ? 'rd-tripping' : ''} ${fx.includes('rainbow') ? 'rd-fx-rainbow' : ''} ${fx.includes('tint') ? 'rd-fx-tint' : ''} ${fx.includes('desat') ? 'rd-fx-desat' : ''} ${fx.includes('breathe') ? 'rd-fx-breathe' : ''} ${fx.includes('shift') ? 'rd-fx-shift' : ''} ${fx.includes('replace') ? 'rd-fx-replace' : ''} ${fx.includes('enhance') ? 'rd-fx-enhance' : ''} ${view === 'home' && !trip ? 'rd-home' : ''}`} style={{ maxWidth: 1200, margin: '0 auto', position: 'relative', isolation: 'isolate', paddingBottom: 20, minHeight: '100vh', display: 'flex', flexDirection: 'column', overflowX: 'clip' }}>
					<div aria-hidden className="rd-molecules" style={{ backgroundImage: MOLECULES }} />
					<div aria-hidden className="rd-molecules b" style={{ backgroundImage: MOLECULES, backgroundPosition: '310px 470px' }} />
					<div aria-hidden ref={glowRef} className="rd-mol-glow" style={{ opacity: view === 'home' && !trip ? 1 : 0 }}>
						<div className="rd-molecules" style={{ backgroundImage: MOLECULES }} />
					</div>
					<header className="mb-10 flex flex-wrap items-center justify-between gap-4" style={{ position: 'relative', zIndex: 2 }}>
						<button onClick={() => goView('home')} aria-label="re:dose home">
							<img src={LOGO_RE_WHITE} alt="re:dose" style={{ height: 24, width: 'auto', display: 'block' }} />
						</button>
						<div className="flex flex-wrap items-center gap-3">
						{view !== 'home' && (
							<GlobalSearch
								subs={rows(pickQ)}
								onSubstance={goSubstance}
								onEffect={goEffect}
								onReport={goReport}
								onCombo={goCombo}
							/>
						)}
						<nav className="flex items-center gap-1">
							{(
								[
									['substances', 'Substances'],
									['reports', 'Experiences'],
									['effects', 'Effects'],
									['resources', 'Resources'],
								] as const
							).map(([v, label]) => (
								<button key={v} className="rd-nav" aria-current={navHere === v ? 'page' : undefined} onClick={() => goView(v)} style={{ whiteSpace: 'nowrap' }}>
									{label}
								</button>
							))}
						</nav>
						</div>
					</header>

					{view === 'reports' && (sub || reportId) && (
						<nav className="mb-6 flex items-center gap-2 text-sm" style={{ color: C.faint, position: 'relative', zIndex: 2 }}>
							<button onClick={() => goView('substances')} style={{ color: C.soft }}>
								Substances
							</button>
							{sub && (
								<>
									<ChevronRight size={14} />
									{reportId ? (
										<button onClick={clearReport} title={sub} style={{ color: C.soft, whiteSpace: 'nowrap' }}>
											{short(sub)}
										</button>
									) : (
										<span title={sub} style={{ color: C.text, fontWeight: 600, whiteSpace: 'nowrap' }}>{short(sub)}{withSub ? ` + ${short(withSub)}` : ''}</span>
									)}
								</>
							)}
						</nav>
					)}

					{view === 'reports' && !sub && !reportId && <StoriesBrowse onOpen={goReport} />}
					{onSub && <ReportsStep sub={sub!} withSub={withSub} only={only} setOnly={(v: boolean) => setOnly(v || (undefined as unknown as boolean))} onCombo={goCombo} pairQ={comboPairQ} pairTimingQ={pairTimingQ} pairMoodQ={pairMoodQ} pairSummaryQ={pairSummaryQ} pairEffectsQ={pairEffectsQ} pairSeqQ={pairSeqQ} q={listQ} kq={kpiQ} curveQ={curveQ} effectsRoute={effectsRoute} denQ={denQ} horizon={horizon} onOpen={(rid) => (setAtLink(undefined as unknown as null), setReportId(rid))} />}
					{onReport && <TimelapseStep id={reportId!} reportQ={reportQ} marksQ={marksQ} dosesQ={dosesQ} obsQ={obsQ} timingQ={timingQ} pairsQ={pairsQ} frozen={!!openItem} />}
					{view === 'home' && <HomePage q={pickQ} onSubstance={goSubstance} onEffect={goEffect} onReport={goReport} onCombo={goCombo} onView={goView} />}
					{view === 'substances' && <SubstancesBrowse q={pickQ} onPick={goSubstance} onCombo={goCombo} />}
					{view === 'effects' && effect && (
						<nav className="mb-6 flex items-center gap-2 text-sm" style={{ color: C.faint, position: 'relative', zIndex: 2 }}>
							<button onClick={() => setEffect(undefined as unknown as null)} style={{ color: C.soft }}>
								All effects
							</button>
							<ChevronRight size={14} />
							<span style={{ color: C.text, fontWeight: 600 }}>{effect}</span>
						</nav>
					)}
					{view === 'effects' && effect && pageFx.length > 0 && (
						<div className="mb-4 flex flex-wrap items-center gap-2 text-xs" style={{ color: C.faint }}>
							<Sparkles size={13} />
							{fxOff ? 'Preview off.' : 'Showing a gentle taste of this effect on the page.'}
							<button onClick={() => setFxOff(!fxOff)} style={{ color: C.soft, textDecoration: 'underline', textUnderlineOffset: 3 }}>
								{fxOff ? 'Turn on' : 'Turn off'}
							</button>
						</div>
					)}
					{view === 'effects' && effect && <EffectPage name={effect} onSubstance={goSubstance} onCombo={goCombo} onEffect={goEffect} onReport={goReport} />}
					{view === 'effects' && !effect && <EffectsBrowse q={effectsQ} onEffect={goEffect} />}
					{view === 'resources' && <ResourcesPage />}
					{view === 'privacy' && <PrivacyPage />}

					<div aria-hidden style={{ flex: 1, minHeight: 64 }} />
					<footer className="flex flex-wrap items-center justify-between gap-x-8 gap-y-3 border-t pt-5 text-sm" style={{ borderColor: C.line, color: C.soft }}>
						<div className="flex flex-wrap items-center gap-x-5 gap-y-2">
							<span className="text-xs" style={{ color: C.faint }}>With thanks to</span>
							{(Object.keys(SOURCES) as (keyof typeof SOURCES)[]).map((k) => (
								<a key={k} className="rd-thanks" href={SOURCES[k].href} target="_blank" rel="noopener noreferrer" title={SOURCES[k].gives} style={{ color: C.soft }}>
									<img src={SOURCES[k].logo} alt="" width={15} height={15} />
									{SOURCES[k].name}
								</a>
							))}
						</div>
						<div className="flex flex-wrap items-center gap-4">
							<button className="rd-thanks" onClick={() => goView('privacy')} title="No cookies, no tracking, no logs" style={{ color: C.soft }}>
								<Lock size={15} />
								Privacy
							</button>
							<a className="rd-thanks" href={REDOSE_DISCORD} target="_blank" rel="noopener noreferrer" title="Talk things through with the re:dose community" style={{ color: C.soft }}>
								<DiscordIcon size={15} />
								Discord
							</a>
							<a className="rd-thanks" href={REDOSE_GITHUB} target="_blank" rel="noopener noreferrer" title="The code behind re:dose" style={{ color: C.soft }}>
								<GitHubIcon size={15} />
								GitHub
							</a>
						</div>
						<p className="w-full text-xs" style={{ color: C.faint, lineHeight: 1.6 }}>
							<b style={{ color: C.soft }}>Not medical advice.</b> re:dose can’t tell you what’s safe for you; experiences are self-reported, and street drugs often aren’t what they’re sold as. In danger? Call your local emergency number. Public domain (
							<a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer" style={{ color: C.soft, textDecoration: 'underline', textUnderlineOffset: 3 }}>CC0</a>) by the{' '}
							<a href="https://ajar.org" target="_blank" rel="noopener noreferrer" style={{ color: C.soft, textDecoration: 'underline', textUnderlineOffset: 3 }}>AJAr Foundation</a>, except our sources’ material: Effect Index text is{' '}
							<a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener noreferrer" style={{ color: C.soft, textDecoration: 'underline', textUnderlineOffset: 3 }}>CC BY-NC-SA 4.0</a> (descriptions shortened); Erowid, TripSit and artists keep their own terms. No affiliation.
						</p>
					</footer>
				</div>
				<DetailPanel item={openItem} onClose={() => setOpenItem(null)} effectQ={effectDetailQ} subQ={subDetailQ} timingQ={subTimingQ} onReplay={goSubstance} onEffectPage={goEffect} />
				{!openItem && <Spunion tips={trip ? ['Whoa… are the letters swimming? Press Esc to come down.', ...spunionTips] : spunionTips} lift={onReport} autoOpen={spunionSpeaks || trip} onPoke={poke} />}
			</main>
		</OpenCtx.Provider>
		</GoCtx.Provider>
	);
}
